setInterval(() => {
  if (lastUpdateTime === null) {
    document.getElementById('last-update-time').textContent = 'Never';
+   updateStatusIndicator('red', 'Disconnected');
  } else {
    const secondsAgo = Math.floor((Date.now() - lastUpdateTime) / 1000);
    document.getElementById('last-update-time').textContent = `${secondsAgo}s ago`;
+   if (secondsAgo < 1) {
+     updateStatusIndicator('green', 'Connected');
+   } else if (secondsAgo < 5) {
+     updateStatusIndicator('yellow', 'Stale');
+   } else {
+     updateStatusIndicator('red', 'Disconnected');
+   }
  }
}, 1000);

+ function updateStatusIndicator(color, text) {
+   const indicator = document.getElementById('connection-status-indicator');
+   indicator.className = `status-${color}`;
+   document.getElementById('status-text').textContent = text;
